const b = ($json && $json.body) ? $json.body : $json;
const cd = b.customData || {};
const transcript = String(cd.call_transcript || '').trim();
const answered_at = String(cd.call_answered_at_timestamp || '').trim();
const duration = String(cd.call_duration_seconds || '').trim();
const recording_url = String(cd.call_recording_url || '').trim();
const is_pickup = !!(transcript || answered_at || duration || recording_url);
const needs_transcription = (!transcript) && !!recording_url;
return { json: {
  contact_id: String(b.contact_id || cd.contact_id || '').trim(),
  email: String(b.email || '').trim(),
  company_name: String(b.full_name || b.first_name || '').trim(),
  transcript: transcript,
  answered_at: answered_at,
  duration: duration,
  call_recording_url: recording_url,
  call_id: String(cd.call_id || '').trim(),
  is_pickup: is_pickup,
  needs_transcription: needs_transcription
}};

const n = $('Normalize Call').item.json;
return { json: {
  contact_id: n.contact_id,
  email: n.email,
  company_name: n.company_name,
  call_id: n.call_id,
  transcript: String($json.transcript || '').trim()
}};

const resp = $json || {};
const opps = Array.isArray(resp.opportunities) ? resp.opportunities : (Array.isArray(resp) ? resp : []);
const t = $('Transcript Ready').item.json;
const pipeOf  = o => String((o && (o.pipelineId || o.pipeline_id)) || '').trim();
const stageOf = o => String((o && (o.pipelineStageId || o.pipeline_stage_id)) || '').trim();

// which CALL pipeline holds an opp (priority: rebooking > conversation > cold)
const COLD_CALL='9E6y34DlG1Imr8FV42RV', CONVERSATION='TwW6o0JdPXUlcwvX0EvI', REBOOKING='smoNRUaagZYOElKFLwtp';
const CALL_PIPES = [
  { key: 'rebooking',    id: REBOOKING },
  { key: 'conversation', id: CONVERSATION },
  { key: 'cold',         id: COLD_CALL },
];
const found = CALL_PIPES.filter(cp => opps.some(o => pipeOf(o) === cp.id));
const chosen = found.length ? found[0] : null;
const route = chosen ? chosen.key : 'none';
const matchedOpp = chosen ? (opps.find(o => pipeOf(o) === chosen.id) || {}) : {};
const anomaly = (found.length === 0) ? 'none' : (found.length > 1 ? 'multiple' : '');

// caller stage -> N (the day) and -> human name. All 15 restructured cold-call stages.
const STAGE_TO_N = {
  '060f44a8-4cd8-4561-8c84-7150bfd57498': 1, '04ccf8e0-383f-4c17-9268-51020233d08b': 1,
  'cb2dc70f-c44e-48fd-b9cc-438901e292ac': 1, '4cb90aaa-b8c3-40a8-b1e6-6585213b258c': 1,
  '648c4952-1ac0-4c8c-9e52-b93efa5ec39e': 1,
  '4b1d7a88-87c0-422b-90e4-b48d16430900': 2, '4b3023aa-515b-40f8-ad82-292ca685562e': 2,
  'ab6ae288-8886-4d4e-ba61-2d6134f585bd': 2, '40bdc040-8e97-4654-ae52-51e458c7f882': 2,
  '59069dd4-8071-45e2-820c-df565ab17132': 2,
  'f8407fb8-f94c-4443-baf9-b7d1c6f50d34': 3, '5bfcb041-6abb-48d2-a60d-511af1af807f': 3,
  '1bd6fb3c-b7bb-40bd-af31-f1c62065c7bb': 3, 'b50e0792-a88c-4d0a-9e44-2d5cebfdef18': 3,
  '21b772e5-385d-47b7-8234-3138bd312a26': 3
};
const STAGE_NAME = {
  '060f44a8-4cd8-4561-8c84-7150bfd57498': 'Day 1 Call A',
  '04ccf8e0-383f-4c17-9268-51020233d08b': 'Day 1 Call A (MGR)',
  'cb2dc70f-c44e-48fd-b9cc-438901e292ac': 'Day 1 Call A (from on hold)',
  '4cb90aaa-b8c3-40a8-b1e6-6585213b258c': 'Day 1 Call B',
  '648c4952-1ac0-4c8c-9e52-b93efa5ec39e': 'Day 1 Call B (MGR)',
  '4b1d7a88-87c0-422b-90e4-b48d16430900': 'Day 2 Call',
  '4b3023aa-515b-40f8-ad82-292ca685562e': 'Day 2 Call (MGR)',
  'ab6ae288-8886-4d4e-ba61-2d6134f585bd': 'Day 2 Call (from on hold)',
  '40bdc040-8e97-4654-ae52-51e458c7f882': 'Day 2 Call (missed call)',
  '59069dd4-8071-45e2-820c-df565ab17132': 'Day 2 Call MGR (missed call)',
  'f8407fb8-f94c-4443-baf9-b7d1c6f50d34': 'Day 3 Call',
  '5bfcb041-6abb-48d2-a60d-511af1af807f': 'Day 3 Call (MGR)',
  '1bd6fb3c-b7bb-40bd-af31-f1c62065c7bb': 'Day 3 Call (from on hold)',
  'b50e0792-a88c-4d0a-9e44-2d5cebfdef18': 'Day 3 Call (missed call)',
  '21b772e5-385d-47b7-8234-3138bd312a26': 'Day 3 Call MGR (missed call)'
};
const cur_stage = stageOf(matchedOpp);
const caller_N = STAGE_TO_N[cur_stage] || 0;
const stage_name = STAGE_NAME[cur_stage] || '';

const context = {
  opp_id: String(matchedOpp.id || '').trim(),
  route: route,
  caller_N: caller_N,
  call_id: String(t.call_id || '').trim(),
  stage_name: stage_name,
  stage_id: cur_stage
};
const state = { processed: false, last_event_log_entry: '', last_call_summary_entry: '', last_signature: '' };

return { json: {
  contact_id: String(t.contact_id || '').trim(),
  transcript: String(t.transcript || ''),
  route: route, caller_N: caller_N, anomaly: anomaly, stage_name: stage_name,
  context_json: JSON.stringify(context),
  state_json: JSON.stringify(state)
}};

const gc = $json || {};
const contact = gc.contact || gc || {};
const cf = id => { const f = (contact.customFields || []).find(x => x.id === id); return f ? (f.value !== undefined ? f.value : f.field_value) : ''; };
let processed = false;
try { const st = JSON.parse(String(cf('BD9TmgEynOEy6bCvZshm') || '{}')); processed = !!st.processed; } catch(e) {}
return { json: {
  contact_id: String(contact.id || $('Transcript Ready').item.json.contact_id || '').trim(),
  call_id: String($('Transcript Ready').item.json.call_id || '').trim(),
  processed: processed,
  fallback: true
}};
